"""Prepare private disposable development config; never provisions host services."""
import argparse
import json
import os
from pathlib import Path
import secrets
import subprocess
from .storage import DDL
from .generate_openhab import generate
from services.observations.registry import Registry


def private_write(path,body):
    path.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
    path.write_text(body);path.chmod(0o600)


def database_sql(runtime_password,chirpstack_password):
    # Values generated by token_hex are safe SQL literals. External passwords are not interpolated.
    import re
    if any(not re.fullmatch('[0-9a-f]{48}',v) for v in (runtime_password,chirpstack_password)):
        raise ValueError('generated random hex database credentials required')
    return f'''CREATE ROLE sensor_writer LOGIN PASSWORD '{runtime_password}';
CREATE SCHEMA earthship_observations;
SET search_path TO earthship_observations,pg_catalog;
{DDL}
INSERT INTO metadata(id,value) VALUES('environment','simulation');
REVOKE ALL ON SCHEMA earthship_observations FROM PUBLIC;
GRANT USAGE ON SCHEMA earthship_observations TO sensor_writer;
GRANT SELECT ON metadata TO sensor_writer;
GRANT SELECT, INSERT ON raw_events, observations, seen TO sensor_writer;
GRANT SELECT, INSERT, UPDATE ON states TO sensor_writer;
CREATE ROLE chirpstack LOGIN PASSWORD '{chirpstack_password}';
CREATE DATABASE chirpstack OWNER chirpstack;
\\connect chirpstack
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS hstore;
'''


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--root',default='deploy/lorawan');args=parser.parse_args()
    root=Path(args.root).resolve();private=root/'private'
    if private.exists():raise ValueError('private configuration already exists; refuse credential rotation over persistent volumes')
    private.mkdir(mode=0o700)
    credentials={name:secrets.token_hex(24) for name in ('ingest','simulator','openhab','chirpstack','gateway','observer','health','db','admin','csdb','redis')}
    accounts=['ingest','simulator','openhab','chirpstack','gateway','observer','health']
    private_write(private/'mqtt.passwords',''.join(f'{name}:{credentials[name]}\n' for name in accounts))
    # Hash in an isolated, networkless disposable container, with no production mounts.
    container=subprocess.check_output(['docker','create','--network','none','--entrypoint','mosquitto_passwd',
        'eclipse-mosquitto:2.0.22','-U','/tmp/passwords'],text=True).strip()
    try:
        subprocess.run(['docker','cp',str(private/'mqtt.passwords'),container+':/tmp/passwords'],check=True)
        subprocess.run(['docker','start','-a',container],check=True,stdout=subprocess.DEVNULL)
        subprocess.run(['docker','cp',container+':/tmp/passwords',str(private/'mqtt.passwords')],check=True)
    finally:subprocess.run(['docker','rm','-f',container],check=True,stdout=subprocess.DEVNULL)
    (private/'mqtt.passwords').chmod(0o600)
    acl='''user ingest
 topic read application/11111111-1111-4111-8111-111111111111/device/+/event/up
 topic read application/11111111-1111-4111-8111-111111111111/device/+/event/join
 topic read us915_1/gateway/+/event/stats
 topic read earthship/simulation/event
 topic write earthship/sensors/v1/#
user simulator
 topic write application/11111111-1111-4111-8111-111111111111/device/+/event/up
 topic write application/11111111-1111-4111-8111-111111111111/device/+/event/join
 topic write us915_1/gateway/aaaaaaaaaaaaaaaa/event/stats
 topic write earthship/simulation/event
user openhab
 topic read earthship/sensors/v1/#
user observer
 topic read earthship/sensors/v1/#
user chirpstack
 topic read us915_1/gateway/+/event/+
 topic read us915_1/gateway/+/state/+
 topic write us915_1/gateway/+/command/+
 topic write application/+/device/+/event/+
user gateway
 topic write us915_1/gateway/+/event/+
 topic write us915_1/gateway/+/state/+
 topic read us915_1/gateway/+/command/+
user health
 topic read earthship/sensors/v1/service
'''
    private_write(private/'mqtt.acl',acl)
    private_write(private/'mosquitto_sub','-h 127.0.0.1\n-p 1883\n-u health\n-P '+credentials['health']+'\n')
    private_write(private/'mosquitto.conf','listener 1883\nallow_anonymous false\npassword_file /mosquitto/config/passwords\nacl_file /mosquitto/config/acl\npersistence true\npersistence_location /mosquitto/data/\nautosave_interval 5\nlog_dest stdout\nlog_type error\nlog_type warning\nmax_packet_size 1048576\n')
    (private/'mqtt_data').mkdir(mode=0o700)
    private_write(private/'postgres_admin',credentials['admin'])
    private_write(private/'init.sql',database_sql(credentials['db'],credentials['csdb']))
    # The private parent is 0700; PostgreSQL's container UID must read this one mounted file.
    (private/'init.sql').chmod(0o644)
    for user in ('ingest','simulator','observer'):
        config=dict(environment='simulation',mqtt_host='mqtt',mqtt_port=1883,mqtt_username=user,mqtt_password=credentials[user],
            chirpstack_probe_url='http://chirpstack:8080/',database_dsn=f'postgresql://sensor_writer:{credentials["db"]}@postgres/sensors_test')
        private_write(private/(user+'.json'),json.dumps(config))
    reg=Registry.read(root/'registry.simulation.json')
    for name,body in generate(reg,dict(host='mqtt',port=1883,username='openhab',password=credentials['openhab'])).items():
        private_write(private/'openhab'/name,body)
    private_write(private/'openhab/services/addons.cfg','package = minimal\nbinding = mqtt\ntransformation = jsonpath,regex\nautomation = jsscripting\n')
    (private/'addons').mkdir(mode=0o700)
    (private/'chirpstack').mkdir(mode=0o700)
    cs=(root/'config/chirpstack.toml').read_text().replace('$POSTGRES_DSN',f'postgres://chirpstack:{credentials["csdb"]}@postgres/chirpstack?sslmode=disable')
    replacements={'$REDIS_URL':f'redis://:{credentials["redis"]}@redis:6379/','$API_SECRET':secrets.token_hex(32),
                  '$MQTT_SERVER':'tcp://mqtt:1883','$MQTT_USERNAME':'chirpstack','$MQTT_PASSWORD':credentials['chirpstack'],'$API_BIND':'0.0.0.0:8080'}
    for key,value in replacements.items():cs=cs.replace(key,value)
    private_write(private/'chirpstack/chirpstack.toml',cs)
    regional=(root/'config/region_us915_1.toml').read_text()
    for key,value in replacements.items():regional=regional.replace(key,value)
    private_write(private/'chirpstack/region_us915_1.toml',regional)
    private_write(private/'redis.conf','bind 0.0.0.0\nappendonly yes\nrequirepass '+credentials['redis']+'\n')
    (private/'redis.conf').chmod(0o644)
    print('Prepared private simulation-only configuration. Add pinned offline OpenHAB addons before starting Compose.')


if __name__=='__main__':main()
